import review_remaining605 as r
b=r.folder(24);old={x['question']['id']:x['question'] for x in r.read(b/'revealed-current.json')}
bodies={
10:('<보고서>\n\n공공조달 시장에서 여성기업 수는 2024년에 공공조달 전체 기업 수의 25% 이상이었고, 2020년 이후 매년 전년 대비 5% 이상 증가하였다.\n\n공공조달 시장에서 여성기업의 계약금액은 매년 증가하여 2024년에 6.7조 원 이상을 달성했으나, 2020년 이후 처음으로 공공조달 전체 기업 계약금액의 10% 미만으로 떨어졌다.\n\n2024년 공공조달 시장에서 여성기업의 계약금액을 발주기관별로 보면 지방자치단체가 가장 큰 비중을 차지했으며, 중앙정부, 공공기관이 그 뒤를 이었다. 공공기관 중에서는 준정부기관이 가장 큰 비중을 차지했으며, 그다음으로는 공기업, 지방공기업, 기타공공기관 순이었다.\n\n한편, 사회적약자기업은 장애인기업, 여성기업, 사회적기업으로만 구성되는데, 사회적약자기업의 공공조달 전체 계약금액은 매년 증가하였다. 특히, 여성기업의 공공조달 계약금액은 매년 사회적약자기업 공공조달 전체 계약금액 중 가장 큰 비중을 차지하고 있다.',0),
11:('<보고서>\n\n2020 ～ 2024년 ‘갑’국 정부의 보건의료 R&D 투자액을 보면, 과기정통부, (가), 식약처의 투자액이 각각 매년 증가하였다. 2024년 보건의료 R&D 투자액의 전년 대비 증가율이 가장 높은 부처는 (나)였다. 전체 R&D 투자액에서 보건의료 R&D 투자액이 차지하는 비중은 매년 5.5% 이상이었으며, 특히 (다)년에 가장 큰 것으로 나타났다.',1),
12:('<보기>\n\nㄱ. 신입생 충원율은 최솟값이 가장 작은 해에 중앙값도 가장 작다.\n\nㄴ. 신입생 충원율의 평균값이 가장 큰 해에 재학생 충원율의 평균값도 가장 크다.\n\nㄷ. 재학생 충원율의 평균값과 중앙값의 차이는 매년 증가한다.\n\nㄹ. 2022년 졸업생 취업률은 다섯 번째로 높은 대학의 값이 평균값보다 크다.',3),
13:('<보기>\n\nㄱ. 가계지출은 2024년이 1980년의 4배 이상이다.\n\nㄴ. 1980년과 2024년 각각 가계지출 중 비소비지출의 비중은 소비지출 중 식료품외지출의 비중보다 크다.\n\nㄷ. 1980년 식료품지출 중 외식지출이 차지하는 비중은 5% 이상이다.\n\nㄹ. 2024년 가계소득이 1980년의 4배일 때, 2024년 가계소득 대비 식료품지출 비율은 1980년보다 낮다.',1),
14:('<보기>\n\nㄱ. 발전단가가 낮은 발전원일수록 연간 발전량이 많다.\n\nㄴ. 발전원별 연간 발전비용은 D가 가장 크다.\n\nㄷ. 발전단가 중 운영단가의 비중이 작은 발전원일수록 연간 발전량이 많다.\n\nㄹ. 발전원별 연간 운영비용은 C가 가장 크다.',3),
15:('<보고서>\n\n2014년 ‘갑’국의 발전원 A ～ D 중 발전단가가 가장 높은 발전원은 (가)였다. ‘갑’국은 발전원 다변화를 위해 보조금 제도를 운영하였고, 2014년에 발전원 (가) 사업자들에게 발전량 1MWh당 (나)천 원의 보조금을 지급하여 사업자 유치를 독려하였다.\n\n이후, 2014년에 비해 2024년 ‘갑’국의 전력 생산 시장에는 많은 변화가 있었다. 발전원 A ～ D의 2024년 발전단가를 분석하면 다음과 같다. 발전원 A는 기술발전으로 시설단가가 90% 줄었으나, 운영단가는 2014년과 같았다. 발전원 B의 경우 노후 발전소를 대체한 신규 발전소 건설로 시설단가가 40% 늘었지만, 운영단가는 2014년과 같았다. 발전원 C와 D는 기존 발전소의 내구연한 연장으로 시설단가가 각각 50%씩 줄었으나, 국제적인 연료비 상승으로 운영단가는 각각 25천 원/MWh, 10천 원/MWh씩 올랐다.\n\n결과적으로 발전원 A ～ D 중, (가)의 발전단가는 2014년에 가장 높았으나, 2024년에는 가장 낮았다. 한편 2024년 발전단가가 가장 높은 발전원은 (다)가 되었다. 2024년에 발전원 (가)와 (다)의 발전단가 차이는 (라)천 원/MWh이었다.',3),
18:('<보기>\n\nㄱ. 2023년에 비해 2024년 실적이 가장 큰 폭으로 감소한 세목은 ‘법인세’이다.\n\nㄴ. 2023년 실적과 2024년 본예산의 차이가 가장 큰 세목은 ‘소득세’이다.\n\nㄷ. 2024년 오차율이 가장 높은 세목은 ‘교통세’이다.\n\nㄹ. 실적이 큰 세목부터 순서대로 나열하면 2023년과 2024년의 순서가 같다.',1)}
assess={10:'기관내순위·세유형합·기업수25%/5%·계약10%조건을 각각 확인해ㄴㄷㄹ. 계산·선지해설 정확.',11:'환경부 단조증가,농식품92/590>15%>과기534/3577,2021보건비중만6%초과. 게시해설92는 원래 정확하며 자체풀이102오기는 별도 정정.',12:'차이절댓값.5/.8/1.5,11개 중앙6번째와5번째>64.3>평균63.6. 순위·유일선지·거리해석 정확.',13:'외식166,지출4배이상,비소비비중반례,소득4배가정의비중하락을 정확히 구별.',14:'A/B단가-발전량 반례,운영비중A/D반례,공통환산계수 생략한 곱에서D발전비용/C운영비용 최대.',15:'명시된산술평균127.5와보조82.5,성분별새단가30/160/100/60으로격차130. 증가율과절대증가구별.',17:'인구·차량·사고 분모를 구분하고260분리기준과각선지반례가 타당. 표·주석 보존.',18:'세열구별,법인감소17.9,소득차10,교통오차율만1/3초과,법인/부가순위역전으로ㄱㄴㄷ.',21:'2023기준생략상한114,스페인잔여164로최소2도시추가. 과거최대도시불확정·5곳증가·서울2021절반초과도정확.',22:'감액341,전액4161,70%·10배·20%임계와감액여집합9%분리기준이정확.'}
ratings=[]
for qid,q in old.items():
 n=q['number'];change=n in bodies or n in [21,22]
 deduction='이미지의 보고서/보기를 원문 그대로 네이티브 본문으로 옮겨 기본 크기에서 읽기 쉽게 한다. 표·그림·수식·주석 자산은 유지한다.' if n in bodies else '선택지의 수치와%기호 사이 공백을 제거해 경계를 복원한다.' if n in [21,22] else '발견 없음.'
 ratings.append(dict(id=qid,scoreBeforeFix=4 if change else 5,assessment=assess[n],deduction=deduction,needsChange=change))
assert not (b/'ratings-before.json').exists()
r.write(b/'ratings-before.json',dict(method='Same-author original/own solve/key/exact arithmetic/host visual pre-edit review. Own d11 arithmetic correction does not lower already-correct published reasoning.',ratings=ratings))
r.write(b/'ratings-frozen.json',dict(frozenAt=r.now(),ratingsSha256=r.sha(b/'ratings-before.json'),total=41,count=10,beforeChanges=True))
changes=[]
for path in (r.ROOT/'assets/psat').glob('*.json'):
 data=r.read(path)
 if not isinstance(data,list):continue
 touched=False
 for q in data:
  if q['id'] not in old or q['number']==17:continue
  before=old[q['id']];assert q==before
  snap=r.OUT/f"before-changes/{q['id']}-r{q['revision']}.json";assert not snap.exists();r.write(snap,before)
  n=q['number']
  if n in bodies:
   body,remove=bodies[n];assert not q['body'];q['body']=body;q['figures']=[f for i,f in enumerate(q['figures']) if i!=remove]
   if n==10:q['figuresAfterBody']=True
  else:q['choices']=[s.replace('50 %','50%').replace('70 %','70%').replace('20 %','20%') for s in q['choices']]
  q['revision']+=1;touched=True
  changes.append(dict(id=q['id'],file=path.relative_to(r.ROOT).as_posix(),oldRevision=before['revision'],newRevision=q['revision'],changedFields=sorted(k for k in q.keys()|before.keys() if k!='revision' and q.get(k)!=before.get(k)),beforeSnapshot=snap.relative_to(r.ROOT).as_posix(),reason='원문 보고서·보기의 기본 글자 가독성 또는 선택지 수치/%경계 개선. 원본표/그래프/수식/주석·이미지파일·기존기록 보존.',status='repaired_pending_reverification'))
 if touched:r.write(path,data)
assert len(changes)==9
r.write(r.OUT/'changes-batch24.json',changes)
print('Frozen41/50;7 prose blocks converted and2percent-choice boundaries fixed. All original asset files retained.')
